use std::env;
use std::collections::HashMap;
use tonic::{transport::Server, Request, Response, Status};
use tonic::metadata::MetadataMap;

pub mod auth_service {
    tonic::include_proto!("auth_service");
}

use auth_service::auth_server::{Auth, AuthServer};
use auth_service::{TokenRequest, TokenResponse, DelegationRequest, DelegationResponse};

#[derive(Debug, Clone)]
pub struct KerberosConfig {
    pub realm: String,
    pub kdc_host: String,
    pub delegation_mode: DelegationMode,
    pub trusted_services: Vec<String>,
    pub max_delegation_depth: u8,
}

#[derive(Debug, Clone, PartialEq)]
pub enum DelegationMode {
    Constrained,
    Unconstrained,
    ResourceBased,
}

impl KerberosConfig {
    pub fn from_env() -> Self {
        let realm = env::var("KRB5_REALM").unwrap_or_else(|_| "CORP.INTERNAL".to_string());
        let kdc_host = env::var("KRB5_KDC").unwrap_or_else(|_| "kdc.corp.internal".to_string());
        let delegation_str = env::var("KRB5_DELEGATION_MODE").unwrap_or_else(|_| "constrained".to_string());
        let trusted_raw = env::var("KRB5_TRUSTED_SERVICES").unwrap_or_else(|_| "".to_string());
        let max_depth_str = env::var("KRB5_MAX_DELEGATION_DEPTH").unwrap_or_else(|_| "1".to_string());

        let delegation_mode = Self::parse_delegation_mode(&delegation_str);
        let trusted_services: Vec<String> = trusted_raw
            .split(',')
            .filter(|s| !s.is_empty())
            .map(|s| s.trim().to_lowercase())
            .collect();
        let max_delegation_depth = max_depth_str.parse::<u8>().unwrap_or(1);

        KerberosConfig {
            realm,
            kdc_host,
            delegation_mode,
            trusted_services,
            max_delegation_depth,
        }
    }

    fn parse_delegation_mode(mode_str: &str) -> DelegationMode {
        // Protocol-level decision: strict matching only for security-critical config
        let normalized = mode_str.trim().to_lowercase();
        match normalized.as_str() {
            "constrained" => DelegationMode::Constrained,
            "resource_based" | "rbcd" => DelegationMode::ResourceBased,
            "unconstrained" => DelegationMode::Unconstrained,
            _ => {
                // Fallback: any unrecognized value defaults to constrained (most restrictive)
                eprintln!("WARNING: Unrecognized delegation mode '{}', defaulting to Constrained", mode_str);
                DelegationMode::Constrained
            }
        }
    }
}

#[derive(Debug)]
pub struct AuthServiceImpl {
    config: KerberosConfig,
    delegation_cache: std::sync::Mutex<HashMap<String, Vec<String>>>,
}

impl AuthServiceImpl {
    pub fn new(config: KerberosConfig) -> Self {
        AuthServiceImpl {
            config,
            delegation_cache: std::sync::Mutex::new(HashMap::new()),
        }
    }

    fn validate_delegation_chain(&self, source_principal: &str, target_service: &str, chain: &[String]) -> bool {
        // Check delegation depth
        if chain.len() as u8 >= self.config.max_delegation_depth {
            return false;
        }

        // In constrained delegation, verify target is in trusted list
        match &self.config.delegation_mode {
            DelegationMode::Constrained => {
                self.config.trusted_services.contains(&target_service.to_lowercase())
            }
            DelegationMode::ResourceBased => {
                // RBCD: the target resource decides who can delegate to it
                // We check if source is allowed by the target's msDS-AllowedToActOnBehalfOfOtherIdentity
                self.check_rbcd_permission(source_principal, target_service)
            }
            DelegationMode::Unconstrained => {
                // Unconstrained delegation: ANY service can be targeted
                // The TGT is cached and can be reused for any service
                true
            }
        }
    }

    fn check_rbcd_permission(&self, source: &str, _target: &str) -> bool {
        // Simulated RBCD check - in production this queries AD
        self.config.trusted_services.iter().any(|s| s == &source.to_lowercase())
    }

    fn issue_delegated_ticket(&self, original_principal: &str, target_service: &str, metadata: &MetadataMap) -> Result<String, Status> {
        let forwarded_tgt = metadata.get("x-krb5-forwarded-tgt")
            .and_then(|v| v.to_str().ok())
            .unwrap_or("");

        let requesting_service = metadata.get("x-krb5-service-principal")
            .and_then(|v| v.to_str().ok())
            .unwrap_or("unknown");

        let mut cache = self.delegation_cache.lock().unwrap();
        let chain = cache.entry(original_principal.to_string()).or_insert_with(Vec::new);

        if !self.validate_delegation_chain(requesting_service, target_service, chain) {
            return Err(Status::permission_denied("Delegation not permitted for target service"));
        }

        chain.push(requesting_service.to_string());

        // Issue S4U2Proxy or forward TGT based on delegation mode
        let ticket = match &self.config.delegation_mode {
            DelegationMode::Unconstrained => {
                // In unconstrained mode, we forward the user's TGT directly
                // This allows the service to impersonate the user to ANY other service
                format!("TGT:{}:{}:forwarded:{}", original_principal, self.config.realm, forwarded_tgt)
            }
            _ => {
                // Constrained: issue a service ticket scoped to the target only
                format!("ST:{}:{}:{}:scoped", original_principal, target_service, self.config.realm)
            }
        };

        Ok(ticket)
    }
}

#[tonic::async_trait]
impl Auth for AuthServiceImpl {
    async fn request_token(&self, request: Request<TokenRequest>) -> Result<Response<TokenResponse>, Status> {
        let req = request.into_inner();
        let token = format!("krb5-token:{}@{}", req.principal, self.config.realm);
        Ok(Response::new(TokenResponse { token, expires_in: 3600 }))
    }

    async fn delegate_access(&self, request: Request<DelegationRequest>) -> Result<Response<DelegationResponse>, Status> {
        let metadata = request.metadata().clone();
        let req = request.into_inner();

        let ticket = self.issue_delegated_ticket(
            &req.original_principal,
            &req.target_service,
            &metadata,
        )?;

        Ok(Response::new(DelegationResponse {
            delegated_ticket: ticket,
            delegation_type: format!("{:?}", self.config.delegation_mode),
        }))
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let config = KerberosConfig::from_env();
    println!("Starting auth service with delegation mode: {:?}", config.delegation_mode);
    println!("Trusted services: {:?}", config.trusted_services);

    let service = AuthServiceImpl::new(config);
    let addr = "[::1]:50051".parse()?;

    Server::builder()
        .add_service(AuthServer::new(service))
        .serve(addr)
        .await?;

    Ok(())
}
